      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"Basic Green Smoothie\",\"description\":\"Quick healthy green smoothie with frozen fruit, greens, and coconut water\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"1 cup frozen fruit\",\"2 cups greens\",\"1 cup coconut water\",\"banana\",\"honey\",\"chia seeds\",\"nut butter\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/basic-green-smoothie#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Add  1 cup frozen fruit  and  2 cups greens  to a  blender .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/basic-green-smoothie#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Add  1 cup coconut water .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 3\",\"url\":\"https://briansunter.com/recipes/basic-green-smoothie#step-3\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Add  banana , a drizzle of  honey , a spoonful of  chia seeds , and a dollop of  nut butter .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 4\",\"url\":\"https://briansunter.com/recipes/basic-green-smoothie#step-4\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Blend until smooth.\"}],\"recipeCuisine\":[\"American\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"keywords\":\"smoothie, breakfast, healthy, quick\",\"recipeYield\":\"1\",\"recipeCategory\":\"breakfast\",\"tool\":[{\"@type\":\"HowToTool\",\"name\":\"blender\"}],\"cookTime\":\"PT5M\",\"totalTime\":\"PT5M\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
