    "structuredData": [
      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"Cranberry Sauce\",\"description\":\"Fresh cranberry sauce with orange zest and cinnamon, cooked down to a jam-like consistency.\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"12 oz fresh or frozen cranberries\",\"1 cup sugar\",\"0.50 cup water\",\"2 strips orange zest\",\"2 tbsp orange juice\",\"cinnamon stick\",\"1 pinch kosher salt\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/cranberry-sauce#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Add  12 oz fresh or frozen cranberries ,  1 cup sugar ,  0.50 cup water ,  2 strips orange zest ,  2 tbsp orange juice ,  cinnamon stick , and a pinch of  1 pinch kosher salt  to a  3-quart saucier or saucepan .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/cranberry-sauce#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Set over medium-high heat and bring to a boil. Reduce to a simmer.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 3\",\"url\":\"https://briansunter.com/recipes/cranberry-sauce#step-3\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Stir occasionally as berries start to pop. Use a  wooden spoon  to press berries against the side of the pan, breaking them down.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 4\",\"url\":\"https://briansunter.com/recipes/cranberry-sauce#step-4\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Continue cooking until the mixture thickens to a jam-like consistency, approximately  10 minutes  total.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 5\",\"url\":\"https://briansunter.com/recipes/cranberry-sauce#step-5\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Remove from heat and let cool for about  30 minutes .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 6\",\"url\":\"https://briansunter.com/recipes/cranberry-sauce#step-6\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Serve immediately or store in a sealed container.\"}],\"recipeCuisine\":[\"American\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"keywords\":\"cranberry, sauce, thanksgiving, holiday, side\",\"recipeYield\":\"10\",\"recipeCategory\":\"sauce\",\"tool\":[{\"@type\":\"HowToTool\",\"name\":\"3-quart saucier or saucepan\"},{\"@type\":\"HowToTool\",\"name\":\"wooden spoon\"}],\"cookTime\":\"PT40M\",\"totalTime\":\"PT40M\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
    ]
