    "structuredData": [
      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"East Carolina BBQ Sauce\",\"description\":\"Thin, spicy, and vinegery BBQ sauce.\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"230 g cider vinegar\",\"13 g brown sugar\",\"6 g coarsely ground pepper\",\"8 g hot pepper sauce\",\"4 g salt\",\"6 g crushed red pepper flakes\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/east-carolina-bbq-sauce#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Combine  230 g cider vinegar  (1 cup)  13 g brown sugar   6 g coarsely ground pepper  (2 tsp)  8 g hot pepper sauce  (2 tsp)  4 g salt  (1 tsp)  6 g crushed red pepper flakes  (1 tsp) in a jar or shaker.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/east-carolina-bbq-sauce#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Seal and shake until sugar has completely dissolved.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 3\",\"url\":\"https://briansunter.com/recipes/east-carolina-bbq-sauce#step-3\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Use or store at room-temperature for up to 2 weeks.\"}],\"recipeCuisine\":[\"american\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"prepTime\":\"PT5M\",\"totalTime\":\"PT5M\",\"isBasedOn\":\"https://www.tasteofhome.com/recipes/east-carolina-bbq-sauce/\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
    ]
