    "structuredData": [
      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"Har Gow\",\"description\":\"Crystal skin shrimp dumplings, a classic dim sum favorite\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"50 g wheat starch\",\"50 g tapioca starch\",\"0.50 g salt\",\"160 ml boiling water\",\"¼ tsp vegetable oil\",\"500 g prawns\",\"2 tsp salt\",\"50 g bamboo shoot\",\"5 g sugar\",\"5 g corn starch\",\"¼ tsp ground white pepper\",\"1 tbsp Shaoxing wine\",\"2 tsp sesame oil\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/har-gow#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Mix the  50 g wheat starch ,  50 g tapioca starch , and  0.50 g salt  in a  mixing bowl .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/har-gow#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Add the  160 ml boiling water  and stir vigorously until it looks like snowflakes.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 3\",\"url\":\"https://briansunter.com/recipes/har-gow#step-3\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Add the  ¼ tsp vegetable oil .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 4\",\"url\":\"https://briansunter.com/recipes/har-gow#step-4\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Knead the dough until soft and pliable.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 5\",\"url\":\"https://briansunter.com/recipes/har-gow#step-5\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Cover and let relax for  5 minutes .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 6\",\"url\":\"https://briansunter.com/recipes/har-gow#step-6\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Put the dough on a  work surface  and roll into long strips.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 7\",\"url\":\"https://briansunter.com/recipes/har-gow#step-7\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Cut dough into small portions, 15–20 g each.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 8\",\"url\":\"https://briansunter.com/recipes/har-gow#step-8\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Roll out the dough and wrap with the shrimp filling.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 9\",\"url\":\"https://briansunter.com/recipes/har-gow#step-9\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Clean and devein the  500 g prawns . Marinate with  2 tsp salt  for  5 minutes  and wash thoroughly under running water.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 10\",\"url\":\"https://briansunter.com/recipes/har-gow#step-10\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Chop the shrimp coarsely.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 11\",\"url\":\"https://briansunter.com/recipes/har-gow#step-11\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Chop the  50 g bamboo shoot  into small pieces.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 12\",\"url\":\"https://briansunter.com/recipes/har-gow#step-12\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Mix the shrimp, bamboo shoots,  5 g sugar ,  5 g corn starch ,  ¼ tsp ground white pepper ,  1 tbsp Shaoxing wine , and  2 tsp sesame oil  until sticky.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 13\",\"url\":\"https://briansunter.com/recipes/har-gow#step-13\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Place the dumplings in a  bamboo steamer .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 14\",\"url\":\"https://briansunter.com/recipes/har-gow#step-14\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Steam for  6 minutes .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 15\",\"url\":\"https://briansunter.com/recipes/har-gow#step-15\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Serve immediately.\"}],\"recipeCuisine\":[\"Chinese\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"keywords\":\"chinese, dim-sum, dumplings, shrimp\",\"recipeYield\":\"15\",\"tool\":[{\"@type\":\"HowToTool\",\"name\":\"mixing bowl\"},{\"@type\":\"HowToTool\",\"name\":\"work surface\"},{\"@type\":\"HowToTool\",\"name\":\"bamboo steamer\"}],\"cookTime\":\"PT16M\",\"totalTime\":\"PT16M\",\"isBasedOn\":\"https://tasteasianfood.com/har-gow/\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
    ]
