    "structuredData": [
      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"Secret Burger Sauce\",\"description\":\"Quick five-minute mayo-based burger sauce, Epicurious&apos;s not-so-secret recipe.\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"0.25 cup mayonnaise\",\"1.50 tsp spicy pickle juice\",\"1.50 tsp ketchup\",\"1 tsp yellow mustard\",\"0.25 tsp smoked paprika\",\"0.25 tsp garlic powder\",\"0.25 tsp onion powder\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/secret-burger-sauce#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Combine  0.25 cup mayonnaise ,  1.50 tsp spicy pickle juice ,  1.50 tsp ketchup ,  1 tsp yellow mustard ,  0.25 tsp smoked paprika ,  0.25 tsp garlic powder , and  0.25 tsp onion powder  in a small  bowl  and stir until well mixed.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/secret-burger-sauce#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Refrigerate until ready to use.\"}],\"recipeCuisine\":[\"american\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"keywords\":\"sauce, condiment, burger\",\"recipeYield\":\"8\",\"recipeCategory\":\"sauce\",\"tool\":[{\"@type\":\"HowToTool\",\"name\":\"bowl\"}],\"cookTime\":\"PT5M\",\"totalTime\":\"PT5M\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
    ]
