    "structuredData": [
      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"Simple Daikon Radish Soup\",\"description\":\"Easy and delicious soup with tender daikon radish in a flavorful kombu dashi broth.\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"300 gram daikon radish\",\"long onion\",\"1200 ml kombu dashi\",\"1 clove garlic\",\"1 tbsp soy sauce\",\"0.50 tbsp salt\",\"pepper to taste\",\"1 tbsp sesame oil\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/simple-daikon-radish-soup#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Slice the  300 gram daikon radish  into small pieces.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/simple-daikon-radish-soup#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Slice the  long onion  into small pieces.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 3\",\"url\":\"https://briansunter.com/recipes/simple-daikon-radish-soup#step-3\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"In a large  pot , combine the  1200 ml kombu dashi ,  1 clove garlic  grated, and daikon slices.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 4\",\"url\":\"https://briansunter.com/recipes/simple-daikon-radish-soup#step-4\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Simmer for  15 minutes  or until the daikon is soft.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 5\",\"url\":\"https://briansunter.com/recipes/simple-daikon-radish-soup#step-5\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Add  1 tbsp soy sauce ,  0.50 tbsp salt , and  pepper to taste .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 6\",\"url\":\"https://briansunter.com/recipes/simple-daikon-radish-soup#step-6\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Add the sliced long onion and simmer for a few more minutes.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 7\",\"url\":\"https://briansunter.com/recipes/simple-daikon-radish-soup#step-7\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Stir in the  1 tbsp sesame oil  just before serving.\"}],\"recipeCuisine\":[\"Japanese\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"keywords\":\"soup, japanese, vegan, daikon, dashi\",\"recipeYield\":\"4\",\"tool\":[{\"@type\":\"HowToTool\",\"name\":\"pot\"}],\"cookTime\":\"PT15M\",\"totalTime\":\"PT15M\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
    ]
