    "structuredData": [
      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"Sous Vide Beef Bulgogi\",\"description\":\"Sous Vide Beef Bulgogi\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"2 tbsp soy sauce\",\"1 tbsp brown sugar\",\"1 tbsp rice wine vinegar\",\"2 tsp fresh ginger\",\"1 clove garlic\",\"1.50 lb flank steak\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/sous-vide-beef-bulgolgi#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Preheat  sous vide immersion circulator  to 130°F.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/sous-vide-beef-bulgolgi#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Combine  2 tbsp soy sauce ,  1 tbsp brown sugar ,  1 tbsp rice wine vinegar , grated  2 tsp fresh ginger , and minced  1 clove garlic  in a  bowl . Mix well to form the marinade.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 3\",\"url\":\"https://briansunter.com/recipes/sous-vide-beef-bulgolgi#step-3\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Place  1.50 lb flank steak  and the marinade in a vacuum bag. Seal according to manufacturer&apos;s instructions.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 4\",\"url\":\"https://briansunter.com/recipes/sous-vide-beef-bulgolgi#step-4\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Cook in the water bath for  2 hours .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 5\",\"url\":\"https://briansunter.com/recipes/sous-vide-beef-bulgolgi#step-5\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Remove steak from bag and pat dry. Sear in a hot  skillet  for  1 minute  per side.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 6\",\"url\":\"https://briansunter.com/recipes/sous-vide-beef-bulgolgi#step-6\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Slice against the grain and serve over rice with desired toppings.\"}],\"recipeCuisine\":[\"Korean\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"keywords\":\"sous-vide, beef, bulgogi, korean, bowls\",\"recipeYield\":\"4\",\"tool\":[{\"@type\":\"HowToTool\",\"name\":\"sous vide immersion circulator\"},{\"@type\":\"HowToTool\",\"name\":\"bowl\"},{\"@type\":\"HowToTool\",\"name\":\"skillet\"}],\"cookTime\":\"PT2H\",\"totalTime\":\"PT2H\",\"isBasedOn\":\"https://web.archive.org/web/20240718125849/https://www.simplyrecipes.com/recipes/sous_vide_beef_bulgogi_bowls/\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
    ]
