    "structuredData": [
      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"Mughlai Saag\",\"description\":\"Spinach with onions, a Mughlai-style saag dish.\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"1 kg spinach\",\"110 gram onions\",\"4 tbsp ghee\",\"110 gram onions\",\"1 kg spinach\",\"green chilli\",\"1 tsp fresh ginger\",\"1 tsp salt\",\"0.50 tsp sugar\",\"125 ml water\",\"0.25 tsp garam masala\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/spinach-with-onions#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Cut the  1 kg spinach  (washed and trimmed) across into  1 cm  wide strips.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/spinach-with-onions#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Chop the  110 gram onions  (peeled) finely.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 3\",\"url\":\"https://briansunter.com/recipes/spinach-with-onions#step-3\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Heat the  4 tbsp ghee  (or vegetable oil) in a fairly large  pot  over a medium-high flame. When hot, put in the  110 gram onions . Stir and fry for  3 minutes .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 4\",\"url\":\"https://briansunter.com/recipes/spinach-with-onions#step-4\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Now put in the chopped  1 kg spinach ,  green chilli  (finely chopped),  1 tsp fresh ginger  (peeled and very finely grated),  1 tsp salt , and  0.50 tsp sugar . Stir and cook for  5 minutes .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 5\",\"url\":\"https://briansunter.com/recipes/spinach-with-onions#step-5\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Pour in the  125 ml water  and bring to a simmer. Cover tightly, reduce the heat to low and cook for  10 minutes . Uncover and boil away some of the extra liquid.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 6\",\"url\":\"https://briansunter.com/recipes/spinach-with-onions#step-6\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Sprinkle the  0.25 tsp garam masala  over the top and mix.\"}],\"recipeCuisine\":[\"Indian\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"keywords\":\"spinach, indian, vegetarian, side\",\"recipeYield\":\"4\",\"recipeCategory\":\"side\",\"tool\":[{\"@type\":\"HowToTool\",\"name\":\"pot\"}],\"cookTime\":\"PT18M\",\"totalTime\":\"PT18M\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
    ]
