      "{\"@context\":\"https://schema.org\",\"@type\":\"Recipe\",\"name\":\"No-Cook Teriyaki Sauce\",\"description\":\"Quick homemade teriyaki sauce with sake, mirin, soy, and oyster sauce\",\"image\":[\"https://briansunter.com/kitchen.jpg\"],\"recipeIngredient\":[\"0.25 cup sake\",\"0.25 cup mirin\",\"0.25 cup soy sauce\",\"0.25 cup oyster sauce\",\"1 tablespoon sugar\"],\"recipeInstructions\":[{\"@type\":\"HowToStep\",\"name\":\"Step 1\",\"url\":\"https://briansunter.com/recipes/teriyaki#step-1\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Combine  0.25 cup sake ,  0.25 cup mirin ,  0.25 cup soy sauce ,  0.25 cup oyster sauce , and  1 tablespoon sugar  in a  bowl .\"},{\"@type\":\"HowToStep\",\"name\":\"Step 2\",\"url\":\"https://briansunter.com/recipes/teriyaki#step-2\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Whisk together all the ingredients until the sugar is dissolved.\"},{\"@type\":\"HowToStep\",\"name\":\"Step 3\",\"url\":\"https://briansunter.com/recipes/teriyaki#step-3\",\"image\":\"https://briansunter.com/kitchen.jpg\",\"text\":\"Store in the fridge for up to a couple weeks.\"}],\"recipeCuisine\":[\"Japanese\"],\"author\":{\"@type\":\"Person\",\"name\":\"Brian Sunter\"},\"keywords\":\"japanese, sauce, teriyaki\",\"recipeYield\":\"4\",\"recipeCategory\":\"sauce\",\"tool\":[{\"@type\":\"HowToTool\",\"name\":\"bowl\"}],\"cookTime\":\"PT5M\",\"totalTime\":\"PT5M\",\"aggregateRating\":{\"@type\":\"AggregateRating\",\"ratingValue\":\"4.5\",\"ratingCount\":\"1\",\"bestRating\":\"5\",\"worstRating\":\"1\"}}"
